const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalogue,products=[],categories=[],shopPage=1,shopCategory='',shopQuery='',shopSort='featured',toastTimer;
let quote=[];try{const saved=JSON.parse(localStorage.getItem('trad-quote')||'[]');if(Array.isArray(saved))quote=saved.filter(x=>typeof x.code==='string'&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=9999)}catch{}
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2}).format(n);
const title=s=>s.split(' ').map(w=>/[0-9]/.test(w)||['LED','COB','ABS','DC','AC','RGB','IC','E27','E14'].includes(w)?w:w.charAt(0).toUpperCase()+w.slice(1).toLowerCase()).join(' ');
function productImage(p){return p.image||p.images?.find(i=>i.width>100&&i.height>90)?.file||p.images?.[0]?.file}
function imageMarkup(p,cls=''){const img=productImage(p);return img?`<img class="${cls}" src="assets/${escapeHtml(img)}" alt="${escapeHtml(p.category)} catalogue family illustration" loading="lazy">`:`<div class="no-photo"><b>✳</b><span>${escapeHtml(p.category)}</span></div>`}
function minPrice(p){const v=p.options.map(o=>Number(o.price)).filter(x=>Number.isFinite(x)&&x>0);return v.length?Math.min(...v):null}
function card(p,tag=''){const price=minPrice(p);return `<article class="product-card"><button class="product-visual" data-product="${escapeHtml(p.id)}" aria-label="View ${escapeHtml(p.name)}">${tag?`<span class="tag">${escapeHtml(tag)}</span>`:''}${imageMarkup(p)}<span class="quick-view">Discover product ↗</span></button><div class="product-meta"><span>${escapeHtml(p.category)}</span><h3><button data-product="${escapeHtml(p.id)}">${escapeHtml(title(p.name))}</button></h3><div class="product-code">${escapeHtml(p.options[0]?.code||'')}${p.options.length>1?' + options':''}</div><div class="price-line"><div>${price!==null?`${p.options.length>1?'From ':''}${money(price)} <small>/ ${escapeHtml(p.options.find(o=>Number(o.price)===price)?.unit?.replaceAll('_',' ')||'unit')}</small>`:'Request pricing'}</div><button data-product="${escapeHtml(p.id)}" aria-label="Choose ${escapeHtml(p.name)} options">+</button></div></div></article>`}
const intro=(eyebrow,heading,description)=>`<section class="page-intro"><div class="breadcrumbs"><a href="#/">Home</a> / ${eyebrow}</div><span class="eyebrow">${eyebrow}</span><h1>${heading}</h1><p>${description}</p></section>`;
const cta=()=>`<section class="project-cta reveal"><div><span class="eyebrow">FROM ONE ROOM TO YOUR NEXT BIG PROJECT</span><h2>Let’s bring your vision <em>to light.</em></h2><p>Tell us what you’re working on. We’ll help you find the right fit.</p></div><a href="#/contact" class="button dark">Start a conversation <span>↗</span></a></section>`;
function home(){return renderShowroom()}
function collectionCard(category,name,desc,num){const p=products.find(p=>p.category===category);return `<a href="#/shop?category=${encodeURIComponent(category)}" class="collection-card reveal"><span class="eyebrow">COLLECTION ${num}</span>${p?imageMarkup(p):''}<div class="card-label"><div><h3>${name}</h3><p>${desc}</p></div><span class="round-arrow">↗</span></div></a>`}
function service(n,heading,text){return `<article class="service reveal"><span>${n} /</span><h3>${heading}</h3><p>${text}</p></article>`}
function lightLab(){return `<section class="inspiration-band"><div class="inspiration-copy reveal"><span class="eyebrow">SAME SPACE. A DIFFERENT FEELING.</span><h2>Set the mood.<br><em>Make it yours.</em></h2><p>Warm and welcoming. Crisp and focused. The colour of your light changes how a space feels. Explore the difference.</p><a href="#/inspiration" class="button light-outline">Find your lighting inspiration <span>↗</span></a></div><div class="light-scene" aria-label="Interactive lighting colour illustration"><div class="scene-wall"></div><div class="scene-line"></div><div class="scene-line second"></div><div class="scene-plinth"></div><div class="scene-circle"></div><div class="temperature-controls" role="group" aria-label="Lighting mood"><button data-temperature="warm" class="selected" aria-pressed="true">Warm white</button><button data-temperature="neutral" aria-pressed="false">Neutral white</button><button data-temperature="cool" aria-pressed="false">Cool white</button></div></div></section>`}
function shop(){return `${intro('The collection','Find your <em>kind of light.</em>','Explore the complete catalogue, featuring Konnice Electric lighting, from architectural LED systems to the electrical essentials behind every great space.')}<div class="shop-layout"><aside class="shop-sidebar"><h2>SHOP BY CATEGORY</h2><div class="category-filters"><button data-category="" class="${!shopCategory?'active':''}">All products <span>${products.length}</span></button>${categories.map(c=>`<button data-category="${escapeHtml(c)}" class="${c===shopCategory?'active':''}">${escapeHtml(c)} <span>${products.filter(p=>p.category===c).length}</span></button>`).join('')}</div><div class="sidebar-note"><strong>Buying for a project?</strong>Add products and quantities to your quote list. Our team can help with wholesale supply.<br><a href="#/contact" class="text-link">Let’s talk ↗</a></div></aside><div><div class="shop-toolbar"><label class="search-box"><span aria-hidden="true">⌕</span><input id="shop-search" type="search" aria-label="Search catalogue" placeholder="Search a product, code or category…" value="${escapeHtml(shopQuery)}"></label><select id="shop-sort" aria-label="Sort products"><option value="featured">Catalogue order</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name: A to Z</option></select></div><div class="results-line"><span id="result-count" aria-live="polite"></span><button id="clear-filters">Reset filters ↺</button></div><div class="shop-products" id="shop-products"></div><nav class="pagination" id="pagination" aria-label="Product pages"></nav><p class="quote-note" style="margin-top:28px">Listed USD retail prices include VAT. Wholesale terms, stock, delivery and installation are confirmed separately. Images illustrate catalogue families; choose a code to view its exact listed specifications.</p></div></div>`}
function renderShop(){let filtered=products.filter(p=>(!shopCategory||p.category===shopCategory)&&(!shopQuery||[p.name,p.category,p.description,...p.options.flatMap(o=>[o.code,o.color,o.specs])].join(' ').toLowerCase().includes(shopQuery.toLowerCase())));if(shopSort==='name')filtered.sort((a,b)=>a.name.localeCompare(b.name));if(shopSort==='price-low')filtered.sort((a,b)=>(minPrice(a)??Infinity)-(minPrice(b)??Infinity));if(shopSort==='price-high')filtered.sort((a,b)=>(minPrice(b)??-1)-(minPrice(a)??-1));const size=12,pages=Math.ceil(filtered.length/size);shopPage=Math.max(1,Math.min(shopPage,pages||1));$('#shop-products').innerHTML=filtered.length?filtered.slice((shopPage-1)*size,shopPage*size).map(p=>card(p)).join(''):`<div class="empty"><h3>No matches, yet.</h3><p>Try a product code, a broader search or another category.</p><button class="button dark" data-reset>Explore all products ↗</button></div>`;$('#result-count').textContent=filtered.length?`${(shopPage-1)*size+1}–${Math.min(shopPage*size,filtered.length)} of ${filtered.length} product families${shopCategory?' · '+shopCategory:''}`:'No products found';$('#pagination').innerHTML=pages>1?`<button data-page="${shopPage-1}" aria-label="Previous page" ${shopPage===1?'disabled':''}>←</button>${Array.from({length:pages},(_,i)=>i+1).filter(n=>n===1||n===pages||Math.abs(n-shopPage)<=1).map((n,i,arr)=>(i&&n-arr[i-1]>1?'<span>…</span>':'')+`<button data-page="${n}" class="${n===shopPage?'active':''}" ${n===shopPage?'aria-current="page"':''}>${n}</button>`).join('')}<button data-page="${shopPage+1}" aria-label="Next page" ${shopPage===pages?'disabled':''}>→</button>`:'';$$('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===shopCategory);b.setAttribute('aria-pressed',String(b.dataset.category===shopCategory))})}
function about(){return `${intro('Our story','Good light starts<br>with <em>good people.</em>','Lighting and electrical supply, with a practical understanding of what your space needs.')}<section class="feature-page"><div><span class="eyebrow">MEET TRAD GROUP</span><h2>Rooted in Lebanon.<br><em>Ready for your vision.</em></h2><p>Based in Maarakeh, in the Tyre district, Trad Group supplies indoor and outdoor lighting, electrical accessories, and sealants and adhesives to customers across Lebanon.</p><p>We work with homeowners, electricians, contractors and designers to help turn a list of requirements into a considered selection. Whether you need a replacement bulb, a continuous line of LED light or products for an entire building, we’re here to help.</p><div class="detail-list"><div><span>01</span><div><h3>A complete collection</h3><p>LED bulbs, panels, spotlights, magnetic tracks, strips, profiles, outdoor lighting and electrical essentials.</p></div></div><div><span>02</span><div><h3>Support beyond the product</h3><p>Lighting design and installation services, with scope, timing and costs confirmed for each project.</p></div></div><div><span>03</span><div><h3>Local roots. Nationwide reach.</h3><p>Visit us at the Tayr Debba–Maarakeh junction, or arrange delivery to your area in Lebanon.</p></div></div></div></div><div class="feature-photo reveal"><small>Architectural lighting inspiration</small></div></section>${cta()}`}
function inspiration(){return `${intro('Lighting inspiration','It’s all in<br><em>the atmosphere.</em>','Think in layers. Consider the mood. Discover how a few thoughtful lighting choices can change the way a space feels.')}<section class="feature-page"><div class="feature-photo reveal"><small>Concept interior · lighting inspiration</small></div><div><span class="eyebrow">A LITTLE LIGHTING KNOW-HOW</span><h2>One room.<br><em>Many layers of light.</em></h2><p>A balanced scheme gives every light a purpose. Start with the room as a whole, add light where you need it, and finish with the details that make it feel like yours.</p><div class="detail-list"><div><span>01</span><div><h3>Ambient light</h3><p>Panels, downlights and linear lighting form the foundation of a comfortable room.</p></div></div><div><span>02</span><div><h3>Task light</h3><p>Focused spotlights and LED strips bring useful light to work surfaces and specific activities.</p></div></div><div><span>03</span><div><h3>Accent light</h3><p>Magnetic tracks, profiles and concealed strips help draw attention to textures and architectural details.</p></div></div></div></div></section>${lightLab()}<section class="section"><div class="section-heading"><div><span class="eyebrow">START WITH YOUR SPACE</span><h2>A different light. <em>For every setting.</em></h2></div></div><div class="inspiration-details"><article class="reveal"><span class="eyebrow">01 / AT HOME</span><h3>A softer kind of living.</h3><p>Explore LED strips and profiles for discreet illumination, with bulbs and downlights to complete your room.</p><a class="text-link" href="#/shop?category=LED%20strips">Explore LED strips ↗</a></article><article class="reveal"><span class="eyebrow">02 / AT WORK</span><h3>Make room for focus.</h3><p>Find panels, linear lights and magnetic track systems for offices, shops and hospitality spaces.</p><a class="text-link" href="#/shop?category=Magnetic%20track%20lights">Explore track lighting ↗</a></article><article class="reveal"><span class="eyebrow">03 / OUTSIDE</span><h3>Beyond the four walls.</h3><p>Discover garden lights, outdoor wall lights, floodlights and solar lighting for your exterior spaces. Confirm the selected model’s suitability for its location.</p><a class="text-link" href="#/shop?category=Garden%20lighting">Explore outdoor lighting ↗</a></article></div></section>${cta()}`}
function contact(){return `${intro('Let’s talk','Your next project<br>starts <em>right here.</em>','A product question, a room to rethink or a complete project to supply. Tell us what you have in mind.')}<section class="contact-layout"><div><span class="eyebrow">COME SAY HELLO</span><h2>Visit. Explore.<br><em>Get inspired.</em></h2><div class="contact-card"><h3>Our location</h3><p>Maarakeh, Tyre district, Lebanon<br>Entrance from Tyre, Tayr Debba–Maarakeh junction.</p><a href="https://www.google.com/maps/search/?api=1&query=Maarakeh%20Tayr%20Debba%20junction%20Lebanon" target="_blank" rel="noopener">Explore the area on Maps ↗</a></div><div class="contact-card"><h3>Opening hours</h3><p>Monday – Saturday · 8:00 am – 4:00 pm<br>Lebanon local time. Confirm Sunday and holiday visits.</p></div><div class="contact-card"><h3>Delivery across Lebanon</h3><p>Tell us your area and order quantities. Our team confirms delivery cost and timing for each order.</p></div><div class="contact-card"><h3>Buying wholesale?</h3><p>Add your product codes and quantities to the quote list. Wholesale terms are confirmed by the store team.</p><button class="text-button quote-trigger" style="margin:10px 0 0">View your quote list ↗</button></div></div><form class="enquiry-form" id="enquiry-form"><h3>Let’s get the details.</h3><p>Prepare your enquiry and download a copy to share with the Trad Group team. This form does not send automatically.</p><div class="selected-summary"><span>${quote.length} selected product option${quote.length===1?'':'s'} in your list</span><button type="button" class="quote-trigger">Review list ↗</button></div><div class="form-grid"><label class="field">Full name *<input name="name" required maxlength="100" autocomplete="name" placeholder="Your name"></label><label class="field">Company / project<input name="company" maxlength="140" autocomplete="organization" placeholder="Optional"></label><label class="field">Phone / WhatsApp *<input name="phone" required maxlength="40" type="tel" autocomplete="tel" placeholder="+961 …"></label><label class="field">Delivery area<input name="area" maxlength="120" autocomplete="address-level2" placeholder="City or region"></label><label class="field wide">I’m interested in<select name="interest"><option>Wholesale product supply</option><option>Products for my home</option><option>Lighting design</option><option>Installation</option><option>Something else</option></select></label><label class="field wide">Tell us about your project *<textarea name="message" required maxlength="3000" placeholder="Products, quantities, room dimensions, project timing…"></textarea></label></div><label class="check-field"><input type="checkbox" required><span>I understand that this prepares a local enquiry file. I will share it with the team to request confirmation and pricing.</span></label><button type="submit" class="button dark full">Prepare & download enquiry <span>↓</span></button><p class="form-status" id="form-status" role="status"></p></form></section><section class="faq"><span class="eyebrow">A FEW THINGS TO KNOW</span><h2 style="margin-top:16px">Before you <em>get started.</em></h2><details><summary>Are catalogue prices wholesale prices?</summary><p>Catalogue prices are USD retail prices including VAT. Wholesale quantities and any trade terms are confirmed by the store. Delivery, installation and other services are quoted separately.</p></details><details><summary>Can you help with design and installation?</summary><p>Yes. Trad Group offers lighting design and installation. The team confirms scope, cost and timing based on your project.</p></details><details><summary>Does the catalogue show live stock?</summary><p>No. Share the exact product codes and quantities with the team to confirm current availability before ordering.</p></details><details><summary>Is there a product warranty?</summary><p>The stated store warranty is one year, with replacement for manufacturing faults. The store confirms claim details and the replacement procedure. General return or exchange terms must be confirmed separately.</p></details></section>`}
function privacy(){return `<article class="privacy"><span class="eyebrow">GOOD TO KNOW</span><h1>Privacy &<br><em>catalogue notes.</em></h1><h2>Your quote list</h2><p>Selected product codes and quantities are stored in your browser on this device so that your list remains available when you return. You can remove items at any time. No account is required.</p><h2>Project enquiries</h2><p>Contact form details are used only to generate the enquiry file you request. This website does not transmit that form to the business. You choose when and how to share your downloaded file.</p><h2>Catalogue information</h2><p>Product names, codes, options, selling units and listed prices are drawn from the owner’s updated catalogue workbook of 14 October 2026. USD prices are retail prices including VAT. The catalogue is not live inventory; availability, wholesale terms, delivery and installation require confirmation by the store. Catalogue images illustrate families and can show related models; rely on the selected code and its listed specifications.</p><h2>Inspiration images</h2><p>The architectural imagery uses concept illustrations for lighting inspiration. It does not represent a completed Trad Group client project or a promise that every pictured fixture is available.</p><h2>External services</h2><p>Fonts may be loaded from Google Fonts, and the location link opens Google Maps. Those services have their own privacy policies.</p><a class="text-link" href="#/contact" style="margin-top:30px">Contact & store information ↗</a></article>`}
async function route(){const raw=location.hash.slice(1)||'/';if(raw==='main'){document.getElementById('main')?.focus();return}if(raw==='collections'){document.getElementById('collections')?.scrollIntoView();return}const [pathname,queryString]=raw.split('?');const routeName=pathname.replace(/^\//,'')||'home';if(!catalogue){$('#main').innerHTML='<div class="loading">Preparing the collection…</div>';return}$$('dialog[open]').forEach(d=>d.close());$('.mobile-nav').hidden=true;$('.menu-trigger').setAttribute('aria-expanded','false');document.body.style.overflow='';if(routeName==='shop'){const params=new URLSearchParams(queryString||'');shopCategory=categories.includes(params.get('category'))?params.get('category'):'';shopPage=1}const renderers={home,shop,about,inspiration,contact,privacy};$('#main').innerHTML=renderers[routeName]?renderers[routeName]():`${intro('Page not found','Let’s find<br><em>the right direction.</em>','The page you’re looking for isn’t here.')}<section class="section"><a class="button dark" href="#/">Back to home ↗</a></section>`;$('#main').className='page-enter';$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===routeName));document.title=`${({home:'Light, beautifully considered.',shop:'Shop the collection',about:'Our story',inspiration:'Lighting inspiration',contact:'Let’s talk',privacy:'Privacy & catalogue notes'})[routeName]||'Page not found'} — Trad Group`;window.scrollTo({top:0,behavior:'instant'});if(routeName==='shop'){renderShop();$('#shop-sort').value=shopSort;$('#shop-search').addEventListener('input',e=>{shopQuery=e.target.value;shopPage=1;renderShop()});$('#shop-sort').addEventListener('change',e=>{shopSort=e.target.value;shopPage=1;renderShop()});$('#clear-filters').onclick=resetFilters}if(routeName==='contact')$('#enquiry-form').onsubmit=downloadEnquiry;observeReveals()}
let observer;function observeReveals(){observer?.disconnect();observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});$$('.reveal').forEach(el=>observer.observe(el))}
function resetFilters(){shopCategory='';shopQuery='';shopSort='featured';shopPage=1;if($('#shop-search'))$('#shop-search').value='';if($('#shop-sort'))$('#shop-sort').value='featured';renderShop();if(location.hash.includes('?'))history.replaceState(null,'','#/shop')}
function openProduct(id){const p=products.find(p=>p.id===id);if(!p)return;$('#product-detail').innerHTML=`<div class="product-detail-grid"><div class="detail-image">${imageMarkup(p)}<small>Catalogue family imagery · exact details follow the selected code.</small></div><div class="detail-info"><span class="eyebrow">${escapeHtml(p.category)}</span><h2>${escapeHtml(title(p.name))}</h2><p>${escapeHtml(p.description)}</p><label for="product-option">Choose your product option</label><select id="product-option">${p.options.map((o,i)=>`<option value="${i}">${escapeHtml(o.code)}${o.color?' · '+escapeHtml(o.color):''}${o.length?' · '+escapeHtml(o.length):''}</option>`).join('')}</select><div class="detail-price" id="detail-price"></div><div class="detail-specs" id="detail-specs"></div><label for="product-qty">Quantity in selling units</label><input type="number" min="1" max="9999" value="1" id="product-qty"><button class="button dark full" id="add-product">Add to quote list <span>+</span></button><p class="quote-note" style="margin-top:14px">Retail catalogue price includes VAT. Ask the team to confirm availability and wholesale terms.</p></div></div>`;const update=()=>{const o=p.options[Number($('#product-option').value)];$('#detail-price').innerHTML=o?.price!==null&&o?.price!==undefined&&Number.isFinite(Number(o.price))?`${money(Number(o.price))}<small>USD / ${escapeHtml(o.unit?.replaceAll('_',' ')||'unit')} · retail, VAT included</small>`:'Request pricing';$('#detail-specs').textContent=o?.specs||'Ask the team for specifications.'};update();$('#product-option').onchange=update;$('#add-product').onclick=()=>{const input=$('#product-qty');if(!input.reportValidity())return;const optionIndex=Number($('#product-option').value),o=p.options[optionIndex];if(!o)return;const qty=Number(input.value);if(!Number.isInteger(qty)||qty<1||qty>9999){input.setCustomValidity('Enter a whole quantity between 1 and 9999.');input.reportValidity();input.setCustomValidity('');return}const existing=quote.find(x=>x.id===p.id&&x.optionIndex===optionIndex);if(existing)existing.qty=Math.min(9999,existing.qty+qty);else quote.push({id:p.id,optionIndex,code:o.code,qty});saveQuote();toast(`${o.code} added to your quote list`);$('#product-dialog').close()};$('#product-dialog').showModal()}
function saveQuote(){try{localStorage.setItem('trad-quote',JSON.stringify(quote))}catch{toast('Your list is available for this visit. Browser storage is unavailable.')}$('#quote-count').textContent=quote.reduce((n,x)=>n+x.qty,0);if($('#quote-dialog').open)renderQuote()}
function quoteData(){return quote.map(item=>{const p=products.find(p=>p.id===item.id),o=p?.options[item.optionIndex];return p&&o?{...item,p,o}:null}).filter(Boolean)}
function renderQuote(){const items=quoteData();$('#quote-items').innerHTML=items.length?items.map((item,i)=>`<div class="quote-row"><div>${imageMarkup(item.p)}</div><div><strong>${escapeHtml(item.o.code)}</strong><small>${escapeHtml(title(item.p.name))}</small><small>${escapeHtml(item.o.unit?.replaceAll('_',' ')||'unit')} · ${item.o.price?money(Number(item.o.price)):'Quote required'}</small><button data-remove="${i}">Remove</button></div><label><span class="eyebrow" style="font-size:8px">QTY</span><input type="number" min="1" max="9999" value="${item.qty}" data-quote-qty="${i}" aria-label="Quantity for ${escapeHtml(item.code)}"></label></div>`).join(''):'<div class="empty"><h3>A bright idea starts here.</h3><p>Add products from the collection to build your list.</p><a class="button dark" href="#/shop">Explore the collection ↗</a></div>';const subtotal=items.reduce((n,x)=>n+(Number(x.o.price)||0)*x.qty,0);$('#quote-summary').innerHTML=items.length?`<div class="quote-summary"><span>Catalogue reference total</span><strong>${money(subtotal)}</strong></div><p class="quote-note">USD retail, VAT included. This is a reference total, not a confirmed order or wholesale quotation. Delivery and services are additional.</p>`:'';$('#quote-continue').hidden=!items.length;$('#download-quote').hidden=!items.length}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function quoteText(){return quoteData().map(({p,o,qty})=>`${o.code} | ${p.name}\nQuantity: ${qty} ${o.unit?.replaceAll('_',' ')||'unit'}\nOption: ${o.color||'as listed'}\nCatalogue retail price: ${o.price?money(Number(o.price)):'confirm with store'} USD per selling unit\n${o.specs||''}`).join('\n\n')}
function downloadEnquiry(e){e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const d=new FormData(form);const text=`TRAD GROUP — PROJECT ENQUIRY\nPrepared: ${new Date().toLocaleDateString('en-GB')}\n\nName: ${d.get('name')}\nCompany / project: ${d.get('company')||'—'}\nPhone / WhatsApp: ${d.get('phone')}\nDelivery area: ${d.get('area')||'To confirm'}\nInterested in: ${d.get('interest')}\n\nProject details\n${d.get('message')}\n\nSELECTED PRODUCTS\n${quoteText()||'No products selected yet.'}\n\nPlease confirm current stock, wholesale pricing, delivery fees and timing. Catalogue retail prices include VAT. This file is an enquiry, not a confirmed order.`;download('Trad-Group-Project-Enquiry.txt',text);$('#form-status').textContent='Your enquiry has been prepared and downloaded. Share the file with the Trad Group team to continue. Nothing has been sent automatically.';toast('Your project enquiry is ready to share')}
document.addEventListener('click',e=>{const product=e.target.closest('[data-product]');if(product)openProduct(product.dataset.product);const category=e.target.closest('[data-category]');if(category){shopCategory=category.dataset.category;shopPage=1;renderShop();history.replaceState(null,'',`#/shop${shopCategory?'?category='+encodeURIComponent(shopCategory):''}`)}const page=e.target.closest('[data-page]');if(page&&!page.disabled){shopPage=Number(page.dataset.page);renderShop();$('.shop-toolbar').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}if(e.target.closest('[data-reset]'))resetFilters();if(e.target.closest('.quote-trigger')){renderQuote();$('#quote-dialog').showModal()}if(e.target.closest('.close-dialog'))e.target.closest('dialog').close();const remove=e.target.closest('[data-remove]');if(remove){const item=quoteData()[Number(remove.dataset.remove)];quote=quote.filter(q=>!(q.id===item.id&&q.optionIndex===item.optionIndex));saveQuote()}const temp=e.target.closest('[data-temperature]');if(temp){const scene=temp.closest('.light-scene');scene.className=`light-scene ${temp.dataset.temperature}`;scene.querySelectorAll('[data-temperature]').forEach(b=>{b.classList.toggle('selected',b===temp);b.setAttribute('aria-pressed',String(b===temp))})}const anchor=e.target.closest('a[href="#collections"]');if(anchor){e.preventDefault();$('#collections')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}});
document.addEventListener('change',e=>{if(e.target.matches('[data-quote-qty]')){const val=Number(e.target.value);if(!Number.isInteger(val)||val<1||val>9999){renderQuote();return}const row=quoteData()[Number(e.target.dataset.quoteQty)];const item=quote.find(q=>q.id===row.id&&q.optionIndex===row.optionIndex);item.qty=val;saveQuote()}});
$('.menu-trigger').onclick=()=>{const nav=$('.mobile-nav');nav.hidden=!nav.hidden;$('.menu-trigger').setAttribute('aria-expanded',String(!nav.hidden))};$('#download-quote').onclick=()=>download('Trad-Group-Product-List.txt',`TRAD GROUP — PRODUCT ENQUIRY LIST\n\n${quoteText()}\n\nCatalogue retail prices include VAT. Confirm availability, wholesale terms and delivery with the store.`);$('#quote-continue').onclick=()=>{$('#quote-dialog').close();if(location.hash==='#/contact')route()};$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#back-top').onclick=()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});window.addEventListener('scroll',()=>$('#back-top').classList.toggle('visible',scrollY>700),{passive:true});$('#year').textContent=new Date().getFullYear();window.addEventListener('hashchange',route);
async function init(){try{const res=await fetch('catalogue.json');if(!res.ok)throw Error('catalogue unavailable');catalogue=await res.json();products=catalogue.products;categories=[...new Set(products.map(p=>p.category))];quote=quote.filter(item=>{const p=products.find(p=>p.id===item.id);return p?.options[item.optionIndex]?.code===item.code});saveQuote();route()}catch(error){$('#main').innerHTML='<div class="loading"><h1>The collection needs a moment.</h1><p>Please refresh this page to try again.</p><button class="button dark" onclick="location.reload()">Try again ↻</button></div>'}}
route();init();
